import type {
  HistoryActivity, HistoryBlock, HistoryChapter, HistoryChoice, HistoryLesson,
  HistoryQuizQuestion, HistorySource, HistoryStep, HistoryTerm, HistoryVisual,
} from "./kanab-quest-school-history-types";

const sid = (key: string) => `cannabinoids-lesson-${key}`;
const tid = (key: string) => `cannabinoids-term-${key}`;
const lid = (chapter: string, number: number) => `cannabinoids-${chapter}-${number}`;
function source(key: string, title: string, author: string, organization: string, published: string, url: string,
  passage: string, access: HistorySource["access"], limitation: string): HistorySource {
  return { id: sid(key), title, author, organization, published, url, passage, access, limitation,
    verifiedAt: "2026-11-12", documentKind: access === "abstract" ? "Résumé original consulté" : access === "excerpt" ? "Passages originaux consultés par indexation" : "Ressource institutionnelle consultée" };
}

