const emergingLessons: readonly HistoryLesson[] = [
  l("emerging-products", 1, {
    title: "Nouveaux noms, preuves inégales", question: "Découvrir une molécule signifie-t-il connaître ses effets humains ?", objective: "Comparer identité, marché et données humaines sans remplir les lacunes.",
    essential: [b("THCP et CBDP ont été identifiés dans le matériel étudié par Citti et ses collègues en 2019. La caractérisation chimique répond à une question d’identité ; les essais de liaison et animaux répondent à d’autres questions. Aucun de ces résultats ne démontre un bénéfice clinique humain ni la composition de tous les produits portant ces noms. Un sigle nouveau ne constitue pas une preuve de meilleure efficacité.", "observation", "citti2019"), b("Le HHC fait l’objet de données humaines émergentes : l’étude exploratoire de 2025 comporte six participants, et des échantillons sont réanalysés en 2026. Ce dossier n’est donc ni vide ni suffisant pour une sécurité générale. Le rapport européen de 2023 décrit par ailleurs un marché de produits semi-synthétiques. Présence naturelle alléguée, procédé commercial et composition réelle doivent rester trois informations distinctes et documentées.", "observation", "hhc2025", "hhc2026", "euda2023")],
    example: b("Une fiche fictive annonce nouveau donc testé chez l’humain. Le lecteur demande la publication exacte : un isolement végétal, un essai sur un récepteur et un essai humain ne sont pas interchangeables.", "fiction", "citti2019", "hhc2025"),
    deeper: [b("Dans un domaine émergent, les cases inconnues doivent être visibles et datées. Une identité peut être bien décrite alors que la proportion des isomères d’un produit, ses constituants non annoncés ou sa tolérance restent mal connus. Les premiers travaux humains apportent des observations utiles, mais un petit effectif ne caractérise pas les événements rares ni les usages prolongés. La surveillance des produits et des intoxications complète la recherche sans remplacer un essai thérapeutique. Enfin, le statut réglementaire dépend d’une substance, d’un usage, d’une juridiction et d’une date : le rapport de marché de 2023 n’est pas une autorisation actuelle.", "interpretation", "hhc2025", "euda2023", "alert2025", "consort2025")],
    visual: v("Une fiche peut être incomplète", [["Identité", "Précise ou encore partielle"], ["Présence naturelle", "Preuve propre à un matériel"], ["Produit", "Fabrication et composition du lot"], ["Humain", "Données disponibles et lacunes datées"]], "La certitude d’une colonne ne se propage pas aux autres.", "citti2019", "euda2023", "hhc2025", "alert2025"),
    activity: a("emerging-products", 1, "choice", "Ni vide, ni dossier complet", "Décrire l’état des preuves humaines sur HHC sans les exagérer.", "Le musée dispose d’une petite étude HHC de 2025 et d’une analyse complémentaire des mêmes échantillons en 2026.", [s("emerging", "Quel résumé convient ?", [["a", "Aucune observation humaine n’existe dans le dossier.", false, "L’étude de 2025 porte bien sur des participants humains."], ["b", "Des observations humaines exploratoires existent, avec des limites importantes.", true, "Cette formulation reconnaît les données sans conclure à une sécurité générale."], ["c", "Deux publications garantissent la sécurité de tous les produits HHC.", false, "Le faible effectif, la cohorte partagée et les différences de produits interdisent cette conclusion."]], [["a", "Un petit dossier humain apporte une information sans couvrir tous les risques et usages.", true, "L’existence de données et leur suffisance sont deux questions distinctes."], ["b", "Tout résultat humain remplace automatiquement l’analyse des lots commerciaux.", false, "La composition de chaque lot reste une question séparée."]], "hhc2025", "hhc2026", "alert2025")], "Décrire les preuves disponibles et les inconnues, avec leur date."), glossary: ["cohort", "hemisynthesis", "lot"], nextQuestion: "Quelle autorité répond à quelle question, et que manque-t-il dans la fiche d’un produit ?",
  }),
  l("emerging-products", 2, {
    title: "La fiche produit à compléter", question: "Un avis d’agence vaut-il une autorisation pour tout usage ?", objective: "Repérer les informations manquantes et le rôle exact des institutions.",
    essential: [b("L’EMA évalue des médicaments et publie leurs dossiers européens ; l’ANSES et l’ANSM participent notamment à l’évaluation des risques et à la vigilance dans leurs domaines. L’EFSA évalue la sécurité alimentaire, tandis que l’EUDA documente les drogues et leurs marchés. Citer une de ces institutions ne suffit pas : il faut nommer le document, sa date, son objet et ce qu’il conclut réellement.", "observation", "ema", "alert2025", "efsa2026", "euda2023"), b("L’actualisation EFSA de février 2026 propose une évaluation provisoire du CBD sous conditions et conserve des incertitudes. Ce n’est ni une AMM ni une autorisation automatique de tout aliment au CBD. Une fiche produit sérieuse sépare identité, composition du lot, origine déclarée, preuves d’effet et statut applicable. Si l’une manque, le lecteur marque information absente au lieu de la déduire d’un logo institutionnel.", "interpretation", "efsa2026", "identity2007", "alert2025")],
    example: b("La fiche fictive porte un logo, le mot naturel et une publication de laboratoire. Elle n’a ni identifiant de lot, ni analyse détaillée, ni usage autorisé précisé. Le lecteur constate ces lacunes sans inventer une composition ou une autorisation.", "fiction", "identity2007", "efsa2026"),
    deeper: [b("Une évaluation de risque peut fixer un cadre scientifique provisoire tout en signalant des populations ou des préparations pour lesquelles la sécurité ne peut être établie. Une autorisation de médicament évalue un produit et des indications ; une alerte de vigilance décrit des problèmes rapportés ; un rapport de marché décrit une situation datée. Ces documents peuvent se compléter, mais aucun ne remplace les autres. La dernière vérification consiste donc à relier chaque phrase de la fiche à la bonne source. La source doit répondre à la question posée, et une conclusion ancienne doit être confrontée aux actualisations disponibles plutôt que présentée comme intemporelle.", "interpretation", "ema", "alert2025", "efsa2026", "euda2023")],
    visual: v("À chaque document sa question", [["EMA", "Médicament et indication"], ["ANSES / ANSM", "Risques et vigilance selon leurs compétences"], ["EFSA", "Évaluation de sécurité alimentaire"], ["EUDA", "Surveillance des drogues et marchés"]], "Rôles illustrés par les documents cités ; avis, alerte et autorisation restent distincts.", "ema", "alert2025", "efsa2026", "euda2023"),
    activity: a("emerging-products", 2, "dossier", "La fiche incomplète", "Identifier ce qu’un document institutionnel ne prouve pas sur un lot.", "Une fiche fictive cite l’EFSA de février 2026 et conclut produit autorisé pour tous. Elle ne précise ni composition du lot ni conditions visées par l’avis.", [s("incomplete", "Quel verdict documentaire est justifié ?", [["a", "L’avis remplace l’analyse du lot et autorise tout usage médical.", false, "Une évaluation alimentaire n’est ni une analyse de ce lot ni une AMM."], ["b", "Le logo suffit à prouver que toutes les populations sont couvertes.", false, "L’avis conserve des restrictions et des incertitudes."], ["c", "La fiche est insuffisante : relier l’avis à son périmètre et documenter le lot et le statut.", true, "Les informations manquantes ne peuvent être déduites de la seule citation."]], [["a", "Chaque document répond à une question et possède un périmètre daté.", true, "Cela empêche de transformer un avis en autorisation universelle."], ["b", "Un avis scientifique positif sur un point élimine toutes les inconnues du produit.", false, "L’identité, la composition et les autres usages restent à documenter."]], "efsa2026", "identity2007", "alert2025")], "Un logo ne remplit pas les cases manquantes d’une fiche."), glossary: ["risk-assessment", "marketing-authorisation", "lot", "uncertainty"], nextQuestion: "Saurez-vous maintenant relier chaque affirmation à la bonne preuve ?",
  }),
];

function checkpoint(chapter: string, title: string, scenario: string, prompt: string, options: readonly Row[], reasons: readonly Row[], keys: readonly string[], takeaway: string): HistoryActivity {
  return a(chapter, "checkpoint", "dossier", title, "Transférer les distinctions du chapitre à un nouveau dossier.", scenario, [s("transfer", prompt, options, reasons, ...keys)], takeaway);
}
