function q(chapterId: string, number: number, lesson: number, prompt: string, texts: readonly [string, string, string, string], keys: readonly string[], difficulty: "easy" | "medium" = "medium"): HistoryQuizQuestion {
  return { id: `cannabinoids-${chapterId}-q${String(number).padStart(2, "0")}`, chapterId, lessonId: "evidence", sectionId: lid(chapterId, lesson), prompt, difficulty,
    options: texts.map((text, index) => ({ id: "abcd"[index], text })), sources: refs(...keys) };
}
